pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is too small to hold even the smallest plausible item,
    // or too small for the lookahead item when it could otherwise nest here.
    if post_residual > 0 {
        if post_residual < 10 {
