    // Open-bin pressure: with many open bins, prefer consolidating into tight fits;
    // with few open bins, tolerate spreading (mild penalty on any placement).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Prefer bins whose residual is already below average (tighter bins close out faster),
    // but only when the fit is reasonably tight.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Early in stream, be slightly more willing to open new bins (keep flexibility);
    // late in stream, favor closing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: competitive baseline; accept it only if no open bin
        // offers a tight fit (score of open bins with small post_residual wins).
        score = 45.0 + pressure * 2.0 - progress * 10.0;
        if next_item_size > 0 {
            // A fresh bin can host anything next; slight bonus.
            score -= 3.0;
        }
    }

    score
}

