pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic polynomial in post_residual, modulated by stream progress.
    // Early on, prefer tight fits (small post_residual); later, waste matters more.
    let mut score = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Smooth cubic coupling: penalize mid-range residuals more as stream progresses.
    let mid = norm_pr * (1.0 - norm_pr);
    score += 2.0 * mid * mid * progress;

    // Lookahead: reward leaving space exactly usable by next item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 1.5 * (-diff / 20.0) * (1.0 - progress) * 1.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // Slight penalty for very full bins when many bins are open (keep flexibility early).
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr * (1.0 - progress);

    // New-bin candidate: make it moderately attractive when residuals are poor.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.05 + norm_pr * (2.0 + 3.0 * progress) - 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * (0.8 - 1.6 * t) + t * t * 0.9;
    score *= poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 18.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space (small unusable residuals) with smooth ramp
    let dead = if next_item_size > 0 {
        ((next_item_size as f64 - pr) / cap).max(0.0)
    } else {
        pr_norm
    };
    score += 12.0 * dead * dead * cap;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Mild penalty when bin residual deviates from mean residual (balance load)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight bias toward opening new bins early, reusing later
    score += 6.0 * (1.0 - t) * (open_bins_count as f64) / (1.0 + open_bins_count as f64);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large dead space quadratically
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: mild reward, scaled by leftover after next
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 - leftover * 0.3;
            if leftover == 0.0 {
                score -= 40.0; // perfect 2-item chain fill
            }
        } else {
            // next item cannot fit in this bin's remainder: penalize small remainders
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    } else {
        // last item: just minimize residual
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate handling: only open a new bin when no open bin offers a good fit
    if bin_residual == bin_capacity {
        // neutral baseline; new bin attractive only if existing bins are fragmented
        score = 70.0 + mean_residual * 0.5 - (fitting_bins_count as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host the next item too
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many bins
    score += open_bins_count as f64 * 0.15;

    score
}

