        score += 5.0 * (next_item_size as f64 / 100.0);
    }

    // Time horizon: early in stream, be more open to new bins (exploration);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == bin_capacity;
    if is_new_bin {
        let exploration_bonus = (1.0 - progress) * 15.0;
        score -= exploration_bonus;
        // New bin more attractive when existing bins are crowded on average.
        score -= (mean_residual / bin_capacity as f64) * 8.0;
        // Penalize new bins when many bins already fit the item (good alternatives exist).
        score += (fitting_bins_count as f64) * 6.0;
    }

    // Favor bins whose residual is below the mean residual (more "used" bins),
    // keeping emptier bins available for future large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty when the item leaves a residual that next_item_size could
    // have used but we consumed the bin anyway (encourage pairing).
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 3.0;
    }

    // Scale slightly with open bin count: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 0.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic polynomial in post_residual, modulated by stream progress.
    // Early on, prefer tight fits (small post_residual); later, waste matters more.
    let mut score = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Smooth cubic coupling: penalize mid-range residuals more as stream progresses.
    let mid = norm_pr * (1.0 - norm_pr);
    score += 2.0 * mid * mid * progress;

    // Lookahead: reward leaving space exactly usable by next item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 1.5 * (-diff / 20.0) * (1.0 - progress) * 1.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // Slight penalty for very full bins when many bins are open (keep flexibility early).
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr * (1.0 - progress);

    // New-bin candidate: make it moderately attractive when residuals are poor.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.05 + norm_pr * (2.0 + 3.0 * progress) - 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space below the smallest
    // possible item (1) is pure waste, but residuals that can host common
    // small classes are valuable. Reward residuals in "usable" classes.
    let cap = bin_capacity as f64;

    // Class thresholds via integer division on post_residual
    let cls = post_residual / 10; // harmonic decile class
    match cls {
        0 => score -= 25.0,                 // 0..9: near-perfect fill, great
        1 => score -= 12.0,                 // 10..19: hosts small items
        2 | 3 => score -= 5.0,              // 20..39: mid-class usable
        4 | 5 | 6 => { /* neutral 40..69 */ }
        _ => score += 8.0,                  // 70+: mostly empty bin, wasteful choice
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: reward proportionally to tightness of the chain fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual; penalize by leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // Prefer new bin for large items or late in stream with poor fits
        let openness = 0.5 * item_frac + 0.3 * (1.0 - progress);
        score += 45.0 - 40.0 * openness;
        // If mean residual across open bins is small, new bin is more justified
        score += 0.2 * (mean_residual / cap).min(1.0);
    } else {
        // Favor reusing bins whose residual is close to the item (tight fit)
        let tightness = 1.0 - (post_residual as f64) / cap;
        score -= 6.0 * tightness * tightness;
    }

    // Penalize leaving residuals that are awkward (just below a mid class,
    // e.g. post_residual in {31..39} can't host 40-class items)
    if post_residual >= 31 && post_residual <= 39 {
        score += 6.0;
    }
    if post_residual >= 61 && post_residual <= 69 {
        score += 4.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is too small to hold even the smallest plausible item,
    // or too small for the lookahead item when it could otherwise nest here.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable sliver: severe penalty scaled by wasted amount.
            score += (10 - post_residual) as f64 * 8.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot host the next item: penalize proportionally to how close it is.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Gap can host the next item: reward nesting.
            score -= 4.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into tight fits;
    // with few open bins, tolerate spreading (mild penalty on any placement).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Prefer bins whose residual is already below average (tighter bins close out faster),
    // but only when the fit is reasonably tight.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Early in stream, be slightly more willing to open new bins (keep flexibility);
    // late in stream, favor closing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: competitive baseline; accept it only if no open bin
        // offers a tight fit (score of open bins with small post_residual wins).
        score = 45.0 + pressure * 2.0 - progress * 10.0;
        if next_item_size > 0 {
            // A fresh bin can host anything next; slight bonus.
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: only attractive if it beats poor fits.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; scale with stream progress and open bins.
        score += 12.0 + 8.0 * (step_index as f64 / total_items.max(1) as f64)
               + 0.5 * open_bins_count as f64;
        // If no open bin fits, opening is the only option -> soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If lookahead item is huge, a fresh bin is more valuable.
        if next_item_size as f64 > mean_residual {
            score -= 6.0;
        }
        return score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-chain: next item exactly fills remaining space -> strong reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.3 * slack;
            if post_residual == next_item_size {
                score -= 10.0; // exact fill, zero waste
            }
        } else {
            // Next item won't fit here: penalize proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.4 * overshoot.min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: mild penalty for wasting scarce large residuals.
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    // Prefer bins whose residual is close to item (tight fits) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64);
    score += 0.2 * (tightness - mean_residual).abs();

    // Discard tiny unusable dead space (<10 can't fit anything in 10..80 streams).
    if post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that can't hold typical future items.
    if post_residual > 0 {
        let dead = (post_residual as f64).ln();
        score += 8.0 * dead;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if post-residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + gap);
        } else {
            let overflow = (next_item_size - post_residual) as f64;
            score += 3.0 * overflow.sqrt();
        }
    }

    // Global state: when many bins are open, discourage spreading; prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 2.0 * pressure * (0.5 + progress);

    // Penalize leaving residual just above awkward sizes (e.g. barely > next item).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score += 10.0;
    }

    // Mild reward for filling existing bins vs. opening new ones early in stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items as f64;

    // Smooth non-linear coupling: progress-weighted dead-space penalty
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += 8.0 * norm_pr * norm_pr * (progress * progress + 0.5 * progress);

    // Reward tight fits more strongly as the stream matures (smooth polynomial)
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus, amplified smoothly over time
    if fitting_bins_count == 1 {
        score -= 5.0 * (0.5 + progress);
    }

    // Lookahead: penalize wasting residual that the next item could use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0) / bin_capacity as f64;
        score += 4.0 * waste * waste;
        // Reward leaving exactly a usable gap for the next item
        let gap_match = 1.0 - ((pr - nxt).abs()) / bin_capacity as f64;
        score -= 3.0 * gap_match * gap_match * (0.4 + 0.6 * progress);
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual coupling
    let spread = open_bins_count as f64 / (total_items as f64).sqrt().max(1.0);
    score += 0.5 * spread * norm_pr * (mean_residual / bin_capacity as f64);

    // Prefer filling bins with low residual relative to mean (smooth coupling)
    score += 2.0 * (pr - mean_residual) / bin_capacity as f64;

    // New-bin candidate: penalize opening fresh bins early, allow later when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) - 2.0 * (mean_residual / bin_capacity as f64) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (frac * 8.0).floor() as i32; // 0..7 harmonic classes of residual size

    // Penalize residuals that are dead space (too small for the smallest plausible item).
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward residuals that form "harmonic" complements: divisible classes that
    // typical future items can exactly fill (modulo-10 structure).
    let exact_fit = if post_residual > 0 { (100 - post_residual % 10) % 10 } else { 0 };
    if exact_fit == 0 && post_residual > 0 {
        score -= 8.0; // residual is a multiple of 10: high chance of exact future fit
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 15.0;
            // harmonic bonus: next item leaves another multiple-of-10 residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 12.0; // next item cannot use this bin's remainder
        }
    }

    // Integer-division threshold on post_residual / next_item_size ratio.
    if next_item_size > 0 {
        let ratio_class = (post_residual as f64 / next_item_size as f64) as u32;
        match ratio_class {
            0 => score += 10.0,      // next item too big for remainder
            1 => score -= 12.0,      // remainder just over one next-item
            2 => score -= 6.0,       // two next-items could fit over time
            _ => score += 2.0,       // large residual: less urgent to fill
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Mean residual coupling: prefer bins near the mean (keeps bin population uniform),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive early in the stream or when residual is hopeless.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let hopeless = post_residual == bin_capacity && (mean_residual < 15.0 || open_bins_count == 0);
        let early = progress < 0.15 && open_bins_count < 3;
        if hopeless || early {
            score -= 25.0;
        } else {
            score += 40.0; // prefer filling existing bins mid/late stream
        }
    }

    // Mild preference for tight fits overall.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits via post_residual, but with a non-linear
    // dead-space penalty: small unusable gaps (< 10) are heavily punished,
    // medium gaps are mildly punished, large gaps are fine.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual < 10 {
        // Unusable dead space: heavy penalty on top of the gap size.
        score += pr * 4.0 + 25.0;
    } else {
        // Usable residual: mild cost proportional to wasted space.
        score += pr * 0.5;
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    // (penalize the new-bin candidate and slightly reward consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 15.0 + bin_pressure * 2.0;
    } else {
        score -= bin_pressure * 0.3;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 15.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            // Next item would create dead space here: mild penalty.
            score += 5.0;
        }
        // Mean residual coupling: bins far from the mean are less attractive.
        score += (pr - mean_residual).abs() * 0.1 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base term,
    // but amplify exact/near-exact completions.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this is a perfect pairing -> strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if next <= post {
            // next item can be chained into this bin
            if gap == 0.0 {
                score -= 40.0;
            } else if gap <= 5.0 {
                score -= 22.0;
            } else {
                // reward proportionally to how well next item fills post space
                score -= 12.0 * (next / post);
            }
        } else {
            // next item cannot fit here; penalize proportionally to the overshoot
            score += 0.08 * (next - post);
        }
    }

    // Compare post_residual against mean residual: creating a residual far
    // below the mean wastes less space than the average bin, slight reward;
    // leaving residual far above mean suggests fragmentation.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (post_f - mean_residual);
    }

    // Last chance: if this is the only bin that fits, prefer using it over
    // opening a new bin (new-bin candidate would score = capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when existing bins can still absorb the item:
    // new-bin candidate gets a penalty that grows with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * progress;
    }

    // Mild penalty for accumulating many open bins with fragmented space
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Lookahead: strongly reward if the next item can still fit in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Dead space for the next item: penalize proportionally to mismatch.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 20.0 * fill;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize opening a new bin, more so when
    // other bins fit and the stream is early; relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 60.0 + 0.2 * open_bins_count as f64;
        penalty *= (1.0 - 0.5 * progress);
        // If the fit elsewhere is bad (large post_residual), new bin less bad.
        penalty -= 0.15 * post_residual as f64;
        score += penalty;
    } else {
        // Prefer bins whose residual is below the mean (consolidate waste),
        // but avoid creating tiny unusable residuals.
        let diff = mean_residual - bin_residual as f64;
        score -= 0.2 * diff;
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny dead space is hard to reuse
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear waste penalty: quadratic coupling of post_residual with progress.
    // Later in the stream, dead space becomes increasingly costly.
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) with a smooth saturating term.
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; mildly penalize stranding space.
        score += 3.0 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin has full residual. Make it attractive only
    // when existing bins would leave large waste or are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let pressure = progress * (1.0 + 0.5 * crowd);
        // Base penalty so a fresh bin is chosen only when waste is large.
        score += 10.0;
        // Reduce penalty as stream progresses or open bins have small residuals.
        score -= 8.0 * pressure;
        // If the item is large relative to capacity, opening a fresh bin is natural.
        score -= 4.0 * (item_size as f64 / cap);
    }

    // Mild global dispersion penalty: prefer bins whose residual is below the mean
    // (fill the emptier-trending bins) with a smooth coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * dev.signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into usable bands.
    // Residuals that can host common small items (>=10) are "alive"; tiny ones are dead.
    if post_residual > 0 {
        let pr = post_residual;
        if pr < 10 {
            // dead space (nothing fits) -> heavy penalty scaled by how dead
            score += 60.0 * (11 - pr) as f64;
        } else if pr < 25 {
            // only tiny items fit -> moderately bad
            score += 25.0;
        } else if pr < 50 {
            // half-capacity class: still flexible
            score += 8.0;
        }
    }

    // Modulo harmonic classes: residuals congruent to multiples of 10 are
    // more likely to be exactly filled by later items from typical streams.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Residuals leaving awkward remainders (mod 5 != 0) are less reusable.
    if post_residual % 5 != 0 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward;
    // if next item cannot fit here at all, this bin wastes its residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits but leaves a new residual; prefer small leftover
            let chain_residual = post_residual - next_item_size;
            score += 0.15 * chain_residual as f64;
            if chain_residual % 10 == 0 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (creates near-dead residual).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 40.0;
    }

    // Tightness reward: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Prefer using bins whose residual deviates from the mean (consolidate waste).
    score += 0.10 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual % 7) as f64;

    // New-bin candidate penalty: opening a bin should only win on near-perfect fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * (bin_capacity - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
