        } else if post_residual > next_item_size {
            score -= 8.0; // next item still fits here: strong bonus
        } else {
            score += 10.0; // next item won't fit: dead space penalty
        }
    } else {
        score -= 5.0; // last item: any fit is fine
    }

    // Relative residual context: prefer bins tighter than the mean.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Early stream: be slightly more willing to fill existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    // New-bin candidate: make it moderately unattractive unless residuals everywhere are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
        if next_item_size > 0 && post_residual == bin_capacity - next_item_size {
            score -= 30.0; // fresh bin pairs perfectly with next item
        }
    }

    score
