pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 8.0;

    // Penalize small dead space that nothing can use (dead zone < 10).
    if post_residual < 10 {
        score -= 6.0; // perfectly closed bin is great
    } else if post_residual <= 20 {
        score += 3.0; // awkward gap zone
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual > 30 {
            score += 8.0; // bad fit in last bin, soften preference
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in stream, opening bins is cheaper; late, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
        // If many open bins already have slack, discourage a new one.
        if mean_residual > item_size as f64 * 1.5 {
            score += 5.0;
        }
    }

    // Lookahead: prefer leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect handoff: this bin can also host the next item.
            let leftover_after_next = post_residual - next_item_size;
            score -= 4.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
            if leftover_after_next < 10 {
                score -= 5.0; // chain of two near-perfect fits
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 2.0; // gap too small for the known next item
        }
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    score += pressure * 0.15;

    // Prefer bins below mean residual (balance load across bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild reward for using larger residual bins (best-fit-like tie-break).
    score -= bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Cubic smooth coupling: late in stream, small residuals matter more
    score += norm_pr.powi(3) * (10.0 + 40.0 * progress * progress);

    // Reward tight fits smoothly: exp decay of post residual
    score -= 8.0 * (-(pr / 15.0)).exp();

    // Lookahead: reward if next item fits into post residual (smooth)
    if next_item_size > 0 {
        let fits = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 6.0 * (fits / cap) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only one bin fits the item
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual is far below mean residual (imbalance)
    score += 2.0 * ((mean_residual - bin_residual as f64) / cap).abs();

    // Encourage consolidating many bins into fewer as stream progresses
    score += 0.5 * open_bins_count as f64 * norm_pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: small leftovers are dead space.
    let post = post_residual;
    if post > 0 {
        // Residue classes: leftovers divisible into common item sizes are reusable.
        let reusable = (post % 10 == 0) as i32
            + (post % 20 == 0) as i32
            + (post % 25 == 0) as i32
            + (post % 50 == 0) as i32;
        score -= 8.0 * reusable as f64;

        // Integer-division thresholds: leftover bucket quality
        let bucket = post / 10; // 0..10 harmonic class
        score += match bucket {
            0 => 40.0,          // 1..9: nearly dead space
            1 => 25.0,          // 10..19
            2 => 12.0,          // 20..29
            3 => 5.0,           // 30..39
            4 => 0.0,
            5 => -4.0,
            6 => -8.0,
            7 => -12.0,
            8 => -16.0,
            9 => -20.0,
            _ => -24.0,         // near-empty bin, very flexible
        };
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Great: chain continues in this bin
            score -= 15.0 + (next_item_size as f64 / cap) * 10.0;
            // Harmonic bonus if next item exactly divides the leftover
            if post % next_item_size == 0 && post > 0 {
                score -= 20.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits only before placement — mild penalty for stealing that room
            score += 6.0;
        }
    } else {
        // Last item: just fill anything, prefer tight fit
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin for nothing
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin would leave a very small, awkward leftover.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score = item leaves capacity - item_size free.
        // Penalize slightly so we only prefer it when existing bins are bad.
        score += 10.0;
        // But if placing here would waste > 60% of an open bin's remaining space, prefer new bin
        if post > 0 && (post as f64 / cap) < 0.10 && bin_residual > item_size {
            score -= 25.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: if this bin is far below average residual,
    // it is "wasted" capacity — favor filling it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
