    // Last-chance bin: keep bins alive when they are the only option,
    // but only if the fit doesn't create a near-dead residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 45.0;
        } else {
            score -= 10.0;
        }
    }

    // Tightness reward: quadratic fill fraction (borrowed, rescaled).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.8 * tightness * tightness * (bin_capacity as f64);
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Prefer consolidating waste: favor bins below the mean residual so
    // emptier bins stay available for future large items.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual % 7) as f64;

    // New-bin candidate: opening a bin should only win on near-perfect fits,
