    if bin_residual == bin_capacity {
        let mut nb = 15.0 + 0.5 * (bin_capacity - post_residual) as f64;
        nb -= (1.0 - progress) * 12.0; // early exploration
        nb -= (mean_residual / bin_capacity as f64) * 10.0; // crowded existing bins -> open new
        nb += (fitting_bins_count as f64) * 7.0; // good alternatives exist -> don't open
        score += nb;
