    // but our placement destroyed that opportunity, penalize.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 3.0;
    }

    // Scale slightly with open bin count: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 0.5 * (post_residual as f64 / bin_capacity as f64);

