        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // strong reward for perfect closure of the current placement
        if post_residual == 0 { score -= 30.0 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity {
        // new-bin candidate: cost scales with how many open bins already fit, and
        // with how much usable space still exists across open bins
        let mut penalty = 4.0 + 2.0 * open_bins_count as f64 ;
        if fitting_bins_count > 0 { penalty += 3.0 * fitting_bins_count as f64 ; }
        if next_item_size > 0 && next_item_size as f64 > mean_residual { penalty -= 2.0 ; }
        if progress > 0.9 { penalty -= 3.0 ; }
        score += penalty ;
        if norm_pr > 0.6 { score += 4.0 ; }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
