pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else if post_residual < 30 { 0.25 } else { 0.0 };
        score += dead * (bin_capacity as f64) * 0.9;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fills relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins;
    // opening a new bin becomes less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    } else if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count as f64).min(15.0);
    }

    // Prefer bins tighter than the mean residual (good packing).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if next item could use the leftover space, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Early stream: allow new bins more freely; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 8.0 * progress;
    }

    score
}

