pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fits.
            score -= 40.0 + 0.5 * next_item_size as f64;
            if next_item_size == post_residual {
                score -= 300.0; // perfect 2-step chain
            }
        } else {
            // Next item won't fit here: penalize, worse if this was the last chance.
            score += 25.0;
            if fitting_bins_count == 1 {
                score += 50.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Slightly prefer bins with residuals below the mean (consolidate waste).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-100.0).min(100.0);

    // Mild penalty for opening a new bin late in the stream when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + 0.1 * post_residual as f64;
    }

    // Penalize large dead space that nothing (>=10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
