        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        // late-stream compaction: prefer tightest fills near the end
        if progress > 0.85 && norm_pr < 0.08 { score -= 4.0 * (0.08 - norm_pr) * cap * 0.1 ; }
        // dead-space guard: residual too small for any plausible future item
        if post_residual < item_size / 3 && fitting_bins_count > 1 { score += 3.0 ; }
    } else {
