    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // new-bin fallback: only attractive when no open bin leaves room for the next item
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && norm_pr > 0.5 { score -= 1.5 ; }
        if open_bins_count > 0 && fitting_bins_count >= 1 && norm_pr > 0.7 { score += 2.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal dead space after placement.
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post / cap);
    score -= fill_ratio * fill_ratio * 30.0;

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        // Exact-ish chaining is best; loose chaining gets partial credit.
        let slack = post - next_item_size as f64;
        score -= 18.0 - slack * 0.15;
    }
    // Penalize bins whose post-residual is just barely too small for the next item
    // (creates stranded near-miss space).
    if next_item_size > 0 && (next_item_size as f64) > post && (next_item_size as f64) - post <= 10.0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Dead-space avoidance: penalize leaving awkward small residuals (5..15) that
    // few future items (min size 10... but interface allows 1..100) can use.
    if post > 0.0 && post < 12.0 {
        score += 12.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large and
    // existing bins are on average quite full (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        let pressure = avg_fill * avg_fill * 45.0; // grows as open bins get full
        let size_pressure = item * 0.35;           // big items justify fresh bins
        let late_bonus = progress * 10.0;          // late in stream, consolidate less
        score += 55.0 - pressure - size_pressure - late_bonus;
    }

    // Mild penalty for spreading across many bins when mean residual is still large.
    if bin_residual != bin_capacity && mean_residual > 40.0 {
        score += 3.0;
    }

    // Slight time-horizon modulation: early on, be a bit greedier about tight fits
    // (long future benefits from compact packing); late, accept adequate fits.
    score *= 1.0 + 0.25 * (1.0 - progress);

    score
}

