                let dil = 1.0 / (fitting_bins_count as f64).max (1.0) ;
                score -= 5.0 * dil ;
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // dead-space penalty: residual too small for anything upcoming
        if next_item_size > 0 && post_residual < next_item_size && post_residual < item_size / 4 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // open a fresh bin only when remaining items are few or current bins are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap ;
        if progress < 0.85 && tight > 0.25 { score -= 2.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalty for dead space that likely cannot be used later
    let usable = (pr as f64 / 100.0).clamp(0.0, 1.0);
    score -= 8.0 * (1.0 - usable * usable) * norm_item;

    // Reward tight fits smoothly
    score -= 15.0 * (-norm_pr * 4.0).exp() * (1.0 - progress * 0.5);

    // Lookahead: does post_residual fit the next item?
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 30.0) * (1.0 - progress);
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.3);
    }

    // Deviation from mean residual: prefer bins near the mean (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.3 + 0.7 * progress);

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
