pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (frac * 4.0).floor() as u32; // 0..3 harmonic quarter classes
    // Penalize odd/harsh classes (small unusable slivers), reward full quarters.
    score += match band {
        0 => 0.0,                    // residual < 25% : near-dead space
        1 => 6.0,                    // 25-50%
        2 => 3.0,                    // 50-75%
        _ => -2.0,                   // 75-100% : roomy bin kept
    };

    // Perfect-fit harmonic class: residual divisible classes via integer division.
    if post_residual == 0 {
        score -= 50.0;               // perfect fill
    } else if post_residual % 10 == 0 {
        score -= 8.0;               // clean decade residual is reusable
    } else if post_residual < 10 {
        score += 15.0;              // sub-10 sliver: dead space penalty
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward tight harmonic match: next item consumes most of remainder
            let nxt_frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nxt_frac;
        } else {
            score += 4.0;           // remainder likely wasted
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is awful.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: comparable to a mid residual plus startup cost.
        score = bin_capacity as f64 * 0.55 + 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0;         // nothing fits: must open new bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    // Stream progression: late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * frac;

    score
}

