pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are essentially unusable
    // for typical items; penalize them harshly with a nonlinear bump.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 13.0).powi(2);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 25 {
        // Moderate penalty for small-ish leftovers scaled by how "wasted" they are.
        score += 0.8 * (post_residual as f64);
    }

    // Reward using a bin whose residual was already fragmented (large residual
    // means the bin is loose; prefer filling loose bins over tight ones).
    score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * (open_bins_count as f64).sqrt();

    // Last-chance bin: strong reward to use the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap -> it becomes dead space.
        score += 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., fitting bins are scarce or mean residual is very low).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 55.0 };
        score += 25.0 + pressure + scarcity;
        // Early stream: opening bins is cheap and keeps flexibility.
        if (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
            score -= 20.0;
        }
    }

    score
}

