                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
                if post_residual < item_size / 2 { score += miss * 0.8 ; }
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
                if post_residual == next_item_size { score -= 5.0 ; }
                // borrowed from best: small leftover still fits next item
                if post_residual < item_size && post_residual >= next_item_size { score += 1.5 ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if progress > 0.85 && norm_pr < 0.08 { score -= 4.0 * (0.08 - norm_pr) * cap * 0.1 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && norm_pr > 0.5 { score -= 1.5 ; }
        if open_bins_count > 0 && fitting_bins_count >= 1 && norm_pr > 0.7 { score += 2.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively via quadratic shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never be used by typical items (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted pairing potential.
            score += 8.0;
        }
    }

    // Prefer filling bins with small residuals relative to the fleet mean (consolidation).
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let open_cost = 20.0 + 60.0 * progress;
        // Opening a new bin is cheap early, expensive late.
        score = open_cost + post_residual as f64;
        // If no existing bin fits well, opening is attractive.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let norm_pr = pr / cap ;
    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
