                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
                // two-step lookahead: bonus if residual after placing next item still fits item_size
                if gap >= item_size as f64 && gap < (item_size as f64) * 2.0 { score -= 2.0 * (1.0 - progress) ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // penalize dead space: residual too small for typical future items
        if next_item_size > 0 && pr > 0.0 && pr < (next_item_size as f64) * 0.5 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // very tight fits are excellent
        if pr < 4.0 { score -= 2.0 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // discourage opening a new bin when a reasonable fit exists
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 4.0 * (1.0 - progress) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Normalized post-residual and its non-linear shaping
    let x = pr / c;
    let base = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream -> tighter packing preferred, penalize large residuals more
    let coupling = base * (0.5 + 0.9 * progress * progress) * (1.0 + 0.3 * (1.0 - x) * progress);

    // Dead-space penalty: residuals too small to be useful grow quadratically
    let dead = (1.0 - x).powi(4) * 8.0;

    // Lookahead: reward if next item fits into post_residual, penalize otherwise
    let lookahead = if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr { -4.0 * (1.0 - n / c) } else { 3.0 * (n - pr) / c }
    } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Mild preference to spread across bins when many are open
    let spread = 0.05 * open_bins_count as f64 * (1.0 - x);

    base + coupling + dead + lookahead + last_chance + spread
}

