pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // ---------- Perfect fit: the bin closes exactly ----------
    if post_residual == 0 {
        return -3.0 * cap - item_size as f64;
    }

    let is_new_bin = bin_residual == bin_capacity;
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };

    // ---------- Harmonic classes of post_residual (capacity fractions) ----------
    // h=0: dead sliver (1..9) | h=1: small (< C/4) | h=2: medium (< C/2) | h=3: large
    let hclass: u8 = if post_residual < 10 {
        0
    } else if post_residual < bin_capacity / 4 {
        1
    } else if post_residual < bin_capacity / 2 {
        2
    } else {
        3
    };

    // Dead sliver: unusable leftover; penalize proportionally to how much
    // usable room this bin had before we fragmented it.
    if hclass == 0 {
        score += 0.6 * bin_residual as f64 + 10.0;
    }

    // ---------- Lookahead coupling (k = 2) ----------
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Next item chains into this bin; reward tight two-item chains.
            score -= 0.5 * (post - nxt) + 0.25 * nxt;
        } else {
            // Near-miss penalty: the closer the miss, the more tempting-but-doomed.
            score += 0.15 * (nxt - post);
        }
    }

    // ---------- Modulo texture: residuals aligned to decimal classes reuse well ----------
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else {
        score += 0.3 * (post_residual % 10) as f64;
    }

    if is_new_bin {
        // ---------- New-bin candidate adjustments ----------
        // Item fits nowhere else: opening a bin is mandatory, reward strongly.
        if fitting_bins_count == 0 {
            score -= 0.5 * cap;
        }
        // Discourage new bins when open bins still hold plenty of loose space.
        score += 0.10 * mr + 2.0 * open_bins_count as f64;
        // Large items naturally justify fresh bins.
        score -= 0.05 * item_size as f64;
    } else {
        // ---------- Last-chance logic on open bins ----------
        if fitting_bins_count == 1 {
            // Only open bin that fits: avoid spawning a new bin if at all reasonable.
            score -= 0.30 * cap;
        } else if fitting_bins_count == 2 {
            score -= 0.10 * cap;
        }
        // Scarce-space pressure: when total open capacity is tight, favor consolidation.
        let tight = mr * open_bins_count as f64 / cap;
        if tight < 1.0 {
            score -= 0.10 * cap * (1.0 - tight);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
