    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but practically tiny gaps) are pure waste -> heavy penalty.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else { 0.0 };
        score += 40.0 * dead;
        // Tight fit reward: fill bins almost exactly.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual != bin_capacity {
        score -= 10.0 * pressure;
    } else {
        // New-bin candidate: penalize more when pressure is high, and when
        // current item is small (wasting capacity on small items).
        score += 15.0 * pressure + (item_size as f64) * 0.1;
        // If next item fits into the fresh bin too, opening is slightly more attractive.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 8.0;
        }
    }

    // Lookahead coupling: prefer bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // gap that blocks the next item
    }

    // Mean-residual anchor: bins deviating far below mean residual are closer to full,
    // favor finishing them off.
    score += 0.2 * (mean_residual - post_residual as f64);

    // Early stream: be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

