pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: reward when next item fits into post_residual
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        }
        // Penalize dead space that next item cannot use
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // Penalize very small unusable residuals (dead space)
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly, unless current bin would leave big dead space
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { 25.0 } else { 0.0 };
        score += 80.0 - lookahead_bonus;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
