    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (low post_residual), scaled softly.
    score = post * 0.5;

    // Harmonic class of post_residual: residues modulo common item sizes.
    // Post-residuals divisible by small classes (10, 20, 25, 50) are "usable".
    let pr = post_residual;
    let mut usable_bonus = 0.0;
    if pr == 0 {
        usable_bonus += 30.0; // perfect closure
    } else {
        if pr % 10 == 0 { usable_bonus += 8.0; }
        if pr % 20 == 0 { usable_bonus += 4.0; }
        if pr % 25 == 0 { usable_bonus += 4.0; }
        if pr % 50 == 0 { usable_bonus += 3.0; }
        // Integer-division thresholds: tiny unusable slivers are penalized.
        if pr < 10 { usable_bonus -= 12.0; }
        else if pr < 20 { usable_bonus -= 5.0; }
    }
    score -= usable_bonus;

    // Lookahead coupling: does post_residual class-match the next item?
    if next_item_size > 0 {
        let ni = next_item_size;
        if pr == ni {
            score -= 25.0; // exact next-fit closure
