            let rem = pr - ni;
            // Reward chains where remainder stays in a usable class.
            if rem % 10 == 0 { score -= 6.0; }
            if rem == 0 { score -= 15.0; }
            if rem < 10 && rem > 0 { score += 6.0; } // creates sliver
            // Penalize wasting most of the bin on a small next item.
            if ni * 3 < pr { score += 4.0; }
        } else {
            // Next item cannot use this bin's remainder at all.
            score += 3.0 + (ni - pr) as f64 * 0.1;
        }
    } else {
