        if post_residual <= 4 && post_residual > 0 { score += (4 - post_residual) as f64 * 1.2 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    if bin_residual == bin_capacity && open_bins_count > 1 && fitting_bins_count > 0 && norm_pr < 0.6 { score += 2.0 * (0.6 - norm_pr) ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space: gaps too small for the minimum item (1) are wasted.
    // Penalize tiny unusable gaps aggressively (strict dead-space avoidance).
    if post_residual > 0 {
        let can_fit_next = next_item_size > 0 && post_residual >= next_item_size;
        if !can_fit_next {
            // Gap unusable for the lookahead item: dead space penalty.
            // Smaller gaps are worse (more trapped capacity relative to use).
            score += 25.0 + 40.0 / (post_residual as f64 + 1.0);
        }
        // Gaps that can still host the next item are mildly favored.
        if can_fit_next {
            score -= 12.0;
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += (open_bins_count as f64).sqrt() * 4.0;

    // New-bin candidate: strongly discourage unless few bins are open
    // or this is a genuinely clean split.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count <= 2 { 0.0 } else { 55.0 + 3.0 * open_bins_count as f64 };
        score += pressure;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it, but only if the fit isn't terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins whose residual is already below average (tighter bins),
    // driving convergence of residuals toward zero.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let norm_pr = pr / cap ;
    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        if post_residual == next_item_size && next_item_size > 0 { score -= 2.0 ; }
        if norm_pr > 0.95 { score -= 2.0 * (norm_pr - 0.95) * 20.0 ; }
