pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact or near-exact fill is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (chain placement).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else if diff <= 5.0 {
            score -= 150.0;
        } else if diff <= 10.0 {
            score -= 60.0;
        } else {
            // Penalize dead space the next item cannot use.
            score += (diff - 10.0) * 2.0;
        }
        // If next item cannot fit anywhere else, prefer keeping space for it.
        if next <= post_residual as f64 {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 250.0 - crowding * 200.0;
    }

    // Early in the stream, allow more bins; later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

