    // Encourage consolidation when many bins are open.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 2.0;

    // Prefer bins with residual below the mean residual (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if post_residual == 0 { 0.0 } else { 1.0 };
        score = 60.0 + poor_fits * 20.0 - desperation * 100.0 - progress * 5.0;
        // A new bin is fine if the item is large and would leave awkward gaps elsewhere
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
