    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Reward tight fits, stronger as stream progresses (quartic in fit quality).
    let fit_quality = 1.0 - norm_pr;
    score -= 12.0 * fit_quality * fit_quality * fit_quality * fit_quality * (0.5 + progress);

    // Penalize dead space below smallest plausible item, smoothly.
    let dead = (20.0 - pr).max(0.0);
    score += 0.15 * dead * dead / 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
