pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but with a dead-zone penalty.
    if post_residual > 0 {
        // Harmonic class of the leftover: leftover mod 10 determines reusability.
        // Leftovers that are multiples of 10 are "harmonic" (common item sizes 10..80
        // include many multiples of 10), so reward them.
        let harmonic = (post_residual % 10) == 0;
        if harmonic {
            score -= 6.0;
        } else {
            // Non-harmonic leftovers create dead space; penalize by residue magnitude.
            let r = (post_residual % 10) as f64;
            score += r * 0.8;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover into usable bands.
    let band = post_residual / 10; // 0..=10
    match band {
        0 => score += 25.0,                 // 0 leftover is perfect (already low)
        1..=2 => score -= 12.0,             // tiny leftovers nearly useless -> penalize
        3..=5 => score -= 4.0,              // mid leftovers usable for small items
        6..=8 => score -= 8.0,              // large leftovers very reusable
        _ => {}
    }

    // Lookahead: if the next item fits the post-residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here: leftover becomes dead space until much later.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the current
    // item leaves a clean harmonic structure for future items, or when open bins
    // are already crowded with large residuals.
    if bin_residual == bin_capacity {
        // Slight default cost so we prefer reusing bins with good fits...
        score += 3.0;
        // ...but if mean residual across open bins is small (bins are full-ish),
        // opening fresh is fine; counteract the cost.
        if mean_residual < 30.0 {
            score -= 10.0;
        }
