        // in any existing bin (large item in fresh bin keeps capacity clean).
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for filling already-open bins as the stream progresses
    // (consolidation effect late in the stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Slight penalty proportional to number of open bins to discourage spreading.
    score += open_bins_count as f64 * 0.05;

    score
}

