        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        // borrowed from best: prefer bins whose leftover exactly fits the next item
        if post_residual < item_size && post_residual >= next_item_size { score += 1.5 ; }
        if progress > 0.85 && norm_pr < 0.08 { score -= 4.0 * (0.08 - norm_pr) * cap * 0.1 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && norm_pr > 0.5 { score -= 1.5 ; }
        if open_bins_count > 0 && fitting_bins_count >= 1 && norm_pr > 0.7 { score += 2.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // since items are >= 1 but typical streams waste them; penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (11.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score += 12.0; // risky small gap even above 10
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Pressure from many open bins: discourage spreading when bins are plentiful.
    score += 0.6 * open_bins_count as f64;

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., mean residual is low or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize opening a new bin when open bins still have room.
        score += 40.0 * openness;
        // Slight discount late in the stream where consolidation matters less.
        score -= 5.0 * progress;
        // If the next item is large, a fresh bin is more valuable.
        score -= (next_item_size as f64) * 0.15;
    }

    // Lookahead: if the post-residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space that even the lookahead can't use
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
