pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: prefer bins where the item fills the residual exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let diff = pr - nr;
            // Exact two-step fill is excellent.
            if diff == 0.0 {
                score -= 55.0;
            } else if diff <= 5.0 {
                score -= 25.0 - 4.0 * diff;
            } else {
                // Penalize leftover dead space relative to lookahead size.
                score += 0.15 * diff;
            }
        } else {
            // Next item cannot follow here; penalize proportionally to wasted capacity.
            score += 0.25 * (nr - pr);
        }
    }

    // Compare post_residual against mean residual: avoid leaving space far below average
    // (creating many small unusable residuals) unless it's a near-perfect fit.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.30 * (mean_residual - pr);
    } else {
        score += 0.10 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when the current
    // item is large relative to capacity (poor fit elsewhere) or late in the stream.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 50.0 * (1.0 - frac) - 20.0 * progress;
        // If lookahead matches a fresh bin's residual nicely, encourage opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Discard new-bin preference when an existing bin is nearly perfect.
        if post_residual == 0 {
            score += 100.0;
        }
    }

    // Tightness bonus: prefer bins that were already tight before placement.
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

