pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Penalize small unusable post-residuals (< next typical item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with smaller residual than the mean (compact bins first),
    // keeping larger residuals for future big items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: later in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let base = 30.0 - fit_ratio * 25.0;
