    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
            }
            // dead-space lookahead: residual that fits neither current nor next item is wasted
            if post_residual < item_size . min (next_item_size) as f64 {
                score += (item_size . min (next_item_size) as f64 - pr) * 2.2 ;
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // two-item lookahead: reward residuals that can chain current + next
        if next_item_size > 0 && post_residual >= (item_size + next_item_size) as u32 { score -= 5.0 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // new-bin decision: penalize opening a fresh bin more strongly late in stream
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (total_items . max (1) as f64) ;
        score += 4.0 + 3.0 * progress + 20.0 * pressure . min (1.0) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes (<= 10) waste almost nothing -> reward.
    let small_waste = if post_residual <= 10 { 1 } else { 0 };
    score -= 25.0 * small_waste as f64;

    // Modulo classes on post_residual: leftovers divisible by common
    // small item sizes (10, 20, 25, 50) are reusable -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Penalize awkward mid-range dead space (11..=19, 21..=24, 26..=29)
    // which few item sizes can fill.
    let awkward = (post_residual >= 11 && post_residual <= 19)
        || (post_residual >= 21 && post_residual <= 24)
        || (post_residual >= 26 && post_residual <= 29);
    if awkward { score += 12.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; leftover becomes dead space
            score += 5.0;
        }
        // Harmonic compatibility: next_item_size residue class matches
        // a divisor of post_residual -> likely future tight fit.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately unattractive unless the
    // current item is huge relative to capacity (best packed fresh).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 20.0 * frac;
        // But if no open bin leaves a good harmonic leftover, new bin ok
        if post_residual == 0 { score -= 10.0; }
    }

    // Stream progression: early on, be pickier about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mild pressure to consolidate when many bins are open.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

