                if gap == 0.0 { score -= 6.0 ; }
                // reward leaving room for next item with margin
                if gap >= 2.0 && gap <= 8.0 { score -= 1.5 ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.5 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.5 * (norm_pr - 0.9) ; }
        let mr = mean_residual ;
        if mr > 0.0 && (pr - mr) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.2 ; }
        if pr > 0.0 && pr < 20.0 { score += (20.0 - pr) as f64 * 1.2 ; }
        if pr <= 2.0 { score -= 8.0 ; }
        // exact fit of current item is ideal
        if post_residual == item_size { score -= 6.0 ; }
        // post residual can still host next item but not item after: mild bonus
        if post_residual >= next_item_size as u32 && post_residual < next_item_size + item_size { score += 1.0 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.32 ; }
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap ;
        score += 6.0 - 10.0 * frac ;
        if fitting_bins_count == 0 { score -= 30.0 ; }
        if frac > 0.6 { score -= 4.0 * (frac - 0.6) * 10.0 ; }
        // open new bin when no open bin fits next item well
        if fitting_bins_count >= 1 && next_item_size as f64 > mean_residual * 1.2 && frac > 0.5 { score -= 2.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let w = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += w * pr_norm * pr_norm * 40.0;

    // Penalize large residuals more as stream progresses (dead space matters late)
    score += (pr_norm * pr_norm * pr_norm) * 30.0 * progress;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    // Slight pull toward bins near mean residual (balance)
    score += (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let norm_pr = pr / cap ;
    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
                // dead-space: residual too small for typical items is wasted space
                if post_residual < 8 { score += (8 - post_residual) as f64 * 1.2 * (1.0 - progress) ; }
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
                // two-item lookahead: can bin also hold item after next?
                if post_residual >= (next_item_size + item_size) as u32 && next_item_size > 0 {
                    score -= 2.0 * (1.0 - progress) ;
                }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // near-perfect fit bonus scaled by progress
        if post_residual <= 2 { score -= 4.0 * (1.0 + progress) ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // discourage opening a new bin when several open bins fit well
    if bin_residual == bin_capacity && fitting_bins_count >= 2 {
        score += 2.0 + 1.5 * (1.0 - progress) ;
    }
    if bin_residual == bin_capacity && open_bins_count > 8 && norm_pr > 0.9 { score += 2.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it partitions by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Reward tight fits: post_residual in the lowest eighth is excellent.
    if pr <= eighth {
        score -= 30.0;
    } else if pr <= quarter {
        score -= 12.0;
    }

    // Penalize dead space: residuals in the awkward band (just above quarter,
    // too big to waste but too small for typical items) get pushed up.
    if pr > quarter && pr < cap / 2.0 {
        score += 8.0;
    }

    // Harmonic class of the item: integer division thresholds.
    let item_class = item_size / 25; // 0: tiny, 1: small, 2: medium, 3: large
    match item_class {
        0 => score += 5.0,   // tiny items fit almost anywhere; don't waste big residuals
        1 => score -= 2.0,
        2 => score -= 4.0,
        _ => score -= 8.0,   // large items should go into the roomiest bins
    }

    // Lookahead coupling: if next item is small, it can fill small residuals,
    // so a moderate post_residual is fine; if next item is large, prefer bins
    // whose post_residual can still host it exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // this bin could also serve the next item: reward chain packing
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        if pr > 0.0 && pr < nxt {
            // residual becomes dead space relative to the next item
            score += 6.0 + 0.1 * nxt;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (tighter bins) slightly.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for consolidating when many bins are open.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make it moderately unattractive unless residual math
    // says otherwise (handled above by dead-space penalties on open bins).
    if bin_residual == bin_capacity {
        score += 15.0 + pr * 0.2;
    }

    // Progress-based mild annealing: later in the stream, be more tolerant
    // of imperfect fits to avoid bin explosion.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

