    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (-8.0 * fit_ratio).exp();

    // Penalize post-residuals that are small but unusable (dead space).
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).sqrt();
        score += 12.0 * dead * (1.0 - dead);
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late.
        score += 20.0 * (1.0 - progress);
        score += open_bins_count as f64 * 0.5;
    } else {
        // Existing bin: small reward growing with progress.
        score -= 5.0 * progress;
    }

    // Prefer bins with residuals below the mean (fill the emptier bins first),
    // keeping fuller bins flexible.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Prefer placing larger items into bins with larger residuals.
    score -= 0.1 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for too many open bins.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let norm_pr = pr / cap ;
    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        // dead-space penalty: small residuals that likely cannot host anything
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        else if post_residual < 30 {
            // refined band: penalize residuals too small for typical mid-size items
            score += (30 - post_residual) as f64 * 0.9 ;
        }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
            }
            // two-step lookahead: reserve space for next two items when tight
            if post_residual >= (next_item_size + item_size) as u32 {
                score -= 2.0 ;
            } else if post_residual >= next_item_size && post_residual < (next_item_size + item_size) as u32 {
                score += 1.0 * (1.0 - progress) ;
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // avoid wasting bins whose residual equals a plausible future item size
        if post_residual >= 20 && post_residual <= 60 && next_item_size as u32 != post_residual {
            score += 0.5 ;
        }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    // new-bin candidate handling: open only when open bins are nearly full or badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { (mean_residual / cap).min(1.0) } else { 0.0 } ;
        if norm_pr > 0.6 { score += 4.0 + 2.0 * fragmentation ; }
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size as f64 > cap * 0.8 {
            score -= 3.0 ;
        }
    }
    score
}

