pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with polynomial shaping.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth penalty for large dead space that is unlikely to be reusable.
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness.powi(2) * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward heavily (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 20.0 * (1.0 - fits_next) * (pr >= nxt) as i32 as f64 * (0.6 + 0.4 * progress);
        // Penalize leaving exactly awkward slivers the next item barely misses.
        let miss = (nxt - pr).abs() / cap;
        score += 15.0 * (1.0 - miss).powi(2) * (pr < nxt) as i32 as f64;
    }

    // Mild penalty proportional to open-bin crowding, smoothed by mean residual alignment.
    let align = 1.0 - ((pr - mean_residual) / cap).abs();
    score += 5.0 * (open_bins_count as f64).ln() * (1.0 - align).max(0.0);

    // New-bin candidate shaping: empty bin gets neutral-ish score unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) - 20.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
