        if post_residual < 6 && next_item_size > post_residual as u32 {
            score += (6 - post_residual) as f64 * 3.0 ;
        }
        // reward residuals that exactly match a plausible two-step chain
        if next_item_size > 0 && post_residual > next_item_size as u32
            && (post_residual - next_item_size as u32) <= item_size / 3 { score -= 2.0 ; }
    } else {
