}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes (or near them) are valuable.
    let post = post_residual;
    if post > 0 {
        // Reward residuals that divide cleanly into capacity fractions (harmonic slots)
        let harmonic_slots = [100u32, 50, 25, 20, 10, 5];
        let mut hbonus = 0.0f64;
        for h in harmonic_slots {
            if post % h == 0 && post >= h {
                hbonus += 6.0 * (post as f64 / h as f64).min(4.0);
            }
        }
        // Reward residuals that are exact multiples of the lookahead item size
        if next_item_size > 0 && post % next_item_size == 0 {
            hbonus += 8.0;
        } else if next_item_size > 0 && post >= next_item_size {
            hbonus += 3.0;
        }
        // Penalize dead space: residuals too small for the minimum item size
        if post < 10 && post > 0 {
            score += 12.0; // nearly unusable sliver
        }
        // Modulo-class penalty: residuals in "awkward" bands (e.g. 11..19, 21..24)
        let m = post % 10;
        if m >= 1 && m <= 4 && post < 40 {
            score += 4.0; // awkward small remainder
        }
        score -= hbonus;
    } else {
        // Perfect fill: strongly favored
        score -= 25.0;
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.85 {
        score -= 10.0 * (fill - 0.85);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize when plenty of
    // open bins exist and mean residual is large (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count > 0 {
            score += mean_residual * 0.25;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
        // If next item is large and this bin would be opened fresh, slight bonus
        if next_item_size >= 60 {
            score -= 4.0;
        }
    }

    // Prefer bins whose residual is below mean (consolidate small residuals)
    if (post as f64) < mean_residual && post > 0 {
        score -= 2.0;
    }

    // Integer-division threshold: bins with residual >= 2*next_item are flexible
    if next_item_size > 0 && post >= 2 * next_item_size {
        score -= 3.0;
    }

    score
}

