    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item + item_size.min(20) {
        score += 60.0; // tiny dead gap
    } else if post_residual <= 10 {
        score += 25.0; // borderline unusable sliver
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (small relative post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

