        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Open-bin pressure: mild penalty for bins whose residual is already small
    // relative to the mean (avoid fragmenting many half-empty bins).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

