    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        if post_residual == 0 { score -= 8.0 ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large dead space quadratically
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: mild reward, scaled by leftover after next
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 - leftover * 0.3;
            if leftover == 0.0 {
                score -= 40.0; // perfect 2-item chain fill
            }
        } else {
            // next item cannot fit in this bin's remainder: penalize small remainders
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    } else {
        // last item: just minimize residual
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate handling: only open a new bin when no open bin offers a good fit
    if bin_residual == bin_capacity {
        // neutral baseline; new bin attractive only if existing bins are fragmented
        score = 70.0 + mean_residual * 0.5 - (fitting_bins_count as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host the next item too
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
