            score += 3.0;
        }
    }

    // Prefer filling already-open bins over opening new ones, especially late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit.
        score += 12.0 + 15.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
