    if bin_residual == bin_capacity {
        let tight = (post_residual as f64) <= 5.0;
        if tight {
            score += 40.0; // never open new bin for perfect fit
        } else {
            score -= 5.0 + 0.3 * (post_residual as f64);
            if open_bins_count > 8 {
                score += 6.0; // discourage bin sprawl
