    let norm_pr = pr / cap ;
    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // dead-space penalty: reward near-perfect compaction more aggressively
        if norm_pr > 0.95 { score -= (norm_pr - 0.95) * cap * 0.6 ; }
        // penalize awkward mid-range residuals that few future items can fill
        if post_residual > 40 && post_residual < 60 { score += 1.2 ; }
        if post_residual > 25 && post_residual < 40 { score += 0.6 ; }
        // lookahead: if two next items fit exactly, strongly prefer
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 2 * next_item_size + 5 {
            score -= 5.0 ;
        }
        // prefer bins whose residual matches next item even at low progress
        if next_item_size > 0 && post_residual == next_item_size { score -= 3.0 * (1.0 - progress) ; }
    } else {
        score -= 25.0 ;
    }
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.3 ; }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // new-bin: discourage opening unless current bins are quite full and item is small
    if bin_residual == bin_capacity {
        if norm_pr > 0.6 && item_size as f64 > 0.5 * mean_residual { score += 6.0 ; }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.2 { score += 3.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; the leftover is likely dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize post residuals that are too small to ever hold a realistic item
    // (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: placing into a bin with residual far above
    // the mean wastes the "freshest" space; prefer bins already below mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when few bins fit the item well or
    // the stream is early; otherwise penalize opening extra bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 80.0 + 60.0 * progress };
        score += pressure;
        // A new bin is relatively better if the current item is large and
        // would leave awkward residue anywhere.
        if item_size >= 60 {
            score -= 40.0;
        }
    }

    // Mild preference for keeping the number of open bins low.
    score += 0.1 * open_bins_count as f64;

    score
}

