pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-fit residual is small
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize unusable dead space: residual too small for the smallest plausible item
    if post_residual < 10u32 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item can use post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream progress and crowding
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 45.0 + 20.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        // If current item nearly fills a fresh bin, opening is attractive
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 35.0;
        }
    } else {
        // Prefer reusing crowded bins when mean residual is high (fragmentation risk)
        let dev = bin_residual as f64 - mean_residual;
        score += 0.10 * dev;
    }

    // Mild time-decay: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
