pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue modulo 10.
    // Leftovers in "harmonic" classes (multiples of 10) are easier to fill
    // by future items; odd/prime-ish residues are dead-space prone.
    let harmonic_class = post_residual % 10;
    let harmonic_bonus: f64 = match harmonic_class {
        0 => 6.0,
        5 => 3.0,
        2 | 4 | 6 | 8 => 1.5,
        _ => -1.5, // odd non-multiple-of-5 residues are awkward
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: small leftovers are fine
    // (nearly full bin), mid leftovers are wasteful.
    let pr = post_residual;
    if pr <= 10 {
        score -= 8.0; // excellent fill
    } else if pr <= 20 {
        score -= 3.0;
    } else if pr <= 40 {
        score += 2.0; // dead zone
    } else if pr <= 60 {
        score += 4.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 25.0;
    }

    // Coupling with next item lookahead: if next item fits exactly into the
    // post residual (or its harmonic multiples), reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        } else if next_item_size > pr {
            score += 3.0; // next item won't fit here: this bin becomes closed stock
        }
    }

    // Last-chance bin: only fitting bin -> avoid opening a new bin unless fit is terrible
    if fitting_bins_count == 1 && pr < item_size.min(20) {
        score -= 10.0;
    }

    // New empty bin candidate: prefer it only when all open bins would leave
    // large awkward residuals or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin if existing residuals are fragmented and many bins open
        score += 30.0 * (1.0 - pressure) * (1.0 - progress);
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.2 {
            score -= 15.0; // fragmentation: fresh bin better than cramming
        }
        if next_item_size > 0 && bin_capacity - next_item_size <= item_size {
            score -= 5.0; // pairing potential in fresh bin
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

