        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        else if post_residual < 30 { score += (30 - post_residual) as f64 * 1.2 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap as u32 <= item_size { score -= 3.0 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 2.0 ; }
            }
        }
        if post_residual == next_item_size { score -= 6.0 ; }
        if post_residual == item_size { score -= 4.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count >= 3 && norm_pr > 0.6 { score += 4.0 * (norm_pr - 0.6) ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
    } else {
        score -= 25.0 ;
    }
    let mr = mean_residual / cap ;
    if norm_pr < mr * 0.5 { score += (mr * 0.5 - norm_pr) * cap * 0.3 ; }
    if pr < mean_residual { score -= 2.0 ; }
    if bin_residual == bin_capacity {
        let tight = (next_item_size as f64 / cap) . min (1.0) ;
        let scarcity = 1.0 / (fitting_bins_count . max (1) as f64) ;
        score += 12.0 + 10.0 * (1.0 - progress) - 6.0 * tight * (1.0 - progress) + 5.0 * scarcity * (1.0 - progress) ;
        if next_item_size == 0 { score -= 4.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // More willing to open a new bin early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (prefer balanced fills).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
