}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), with super-linear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward bins whose post-residual closely matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect match for the next item is highly desirable
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // If next item cannot fit here anyway, slight penalty for wasting lookahead
        if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Reward filling bins tighter than the current mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving dead space below the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: neutral baseline, adjusted by context.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins would leave very poor fits
        // or when the current bin is already crowded.
        let poor_fit_threshold = 0.35 * bin_capacity as f64;
        if post_residual as f64 >= poor_fit_threshold && fitting_bins_count > 0 {
            score -= 15.0; // open a fresh bin rather than fragment an old one
        } else {
            score += 30.0; // keep using open bins when fit is decent
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64;

    score
}

