pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual (low dead space).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness) * (item_size as f64) / 100.0;

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // sliver waste
    }

    // Lookahead: reward leaving residual that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // chain: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / 100.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing ones
    // (make new bins less attractive when open_bins_count is high).
    let crowding = (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus crowding penalty; attractive only if
        // current bin fit is bad (large post_residual) and mean residual is low.
        score += 25.0 + 90.0 * crowding - 0.15 * mean_residual;
    } else {
        // Existing bin: small bonus for keeping bin count stable.
        score -= 10.0 * crowding;
    }

    // Time horizon: early in the stream, be conservative with new bins (long stream
    // amortizes consolidation); late in the stream, tighter fits matter more.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - tightness);

    // Global residual alignment: prefer bins whose residual deviates below the mean
    // (fill down the "loose" bins first to normalize the pool).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.05 * dev;
    }

    // Mild size-aware tiebreak: bigger items deserve better fits.
    score -= 0.1 * (item_size as f64) * tightness;

    score
}

