    // already fragmented; prefer filling fragmented bins.
    if (bin_residual as f64 - mean_residual).abs() > 0.0 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0; // below-average residual: close it out
        } else {
            score += 2.0;
        }
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 15.0;
    } else if fill_ratio > 0.6 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }
    if post_residual > 12 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count > 4 {
        score += 3.0 * (fitting_bins_count as f64 - 4.0);
    }

    // Open-bin pressure: penalize using bins when many are open,
    // nudging toward consolidation unless the fit is good.
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is close to post_residual but slightly larger, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    // to preserve large gaps in other bins for future items.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: baseline score with mild early-stream preference,
    // penalized when many bins are already open (favor consolidation).
    if bin_residual == bin_capacity {
        score = 55.0 + 1.5 * open_bins_count as f64 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pr = post_residual as f64 ;
    let norm_pr = pr / cap ;
    let mut score = pr * 0.80 + (norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * (1.0 - progress)) * 0.20 ;
    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.32 ; }
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
                // dead space: residual too small for anything typical
                if post_residual < 6 && progress > 0.5 { score += 4.0 ; }
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
                // two-item lookahead: bin can absorb next item AND still hold more
                if post_residual >= (next_item_size + item_size) as f64 { score -= 2.5 * (1.0 - progress) ; }
            }
        }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        // reward near-perfect compaction more aggressively late in the stream
        if norm_pr < 0.03 { score -= 3.0 + 3.0 * progress ; }
    } else {
        score -= 25.0 ;
    }
    if bin_residual == bin_capacity && norm_pr > 0.6 { score += 4.0 ; }
    // discourage opening a new bin while open bins remain loosely packed
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 && mean_residual / cap > 0.35 {
        score += 6.0 * (mean_residual / cap - 0.35) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: residual within small slack of 0 is excellent.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a double win — strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 4.0 {
                score -= 20.0 - slack * 2.0;
            } else {
                // residual too big vs next item: mild penalty for hoarding space
                score += slack * 0.15;
            }
        } else {
            // next item cannot fit here; post residual becomes dead space
            // unless small enough to be generally useful.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.4;
        }
    }

    // Penalize creating unusable slivers relative to the smallest possible item (1..100, assume ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // filling a bin that is already tighter than average is good.
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.1;

    // Prefer consolidating into fewer bins early on; encourage new bins only
    // when many bins are open and residual is large/wasteful.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when the fit would be very tight
        // or when open bins are highly fragmented (high mean residual).
        score += 30.0;
        score += mean_residual * 0.3;
        if item_size >= 90 {
            score -= 10.0; // huge items: fresh bin is fine
        }
    } else {
        // mild reward for using existing bins as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack_after_next / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual can't host next item: mild penalty scaled by wasted potential.
        score += 4.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into bins below the mean (balancing residuals).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.08 * dev;
    }

    // Time horizon: late in the stream, be conservative — prefer tight packing,
    // avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 0.0 } else { 15.0 + 10.0 * (1.0 - progress) };
        score += base_penalty + scarcity_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr as f64;

    // Smooth non-linear coupling: post_residual penalized more later in stream
    let late = 0.5 + 0.5 * progress;
    score += 40.0 * norm_pr * norm_pr * late;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (1.0 - norm_pr).powi(3);
    score -= 30.0 * dead;

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 25.0 * fit_quality;
        } else {
            score += 10.0 * (ns - pr) / cap;
        }
    }

    // Mean residual coupling: avoid diverging from average fill state
    let dev = (mean_residual - pr).abs() / cap;
    score += 8.0 * dev * dev;

    // Crowding: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless current bin would be wasteful
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Modulo classes: residuals that are multiples of 10 are "harmonic" slots
    // (likely to be filled by future items from a 10-quantized stream).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    } else {
        // Non-harmonic dead space penalty grows with smallness of residual.
        score += (10.0 - (post_residual % 10) as f64) * 6.0;
    }

    // Integer-division thresholds: classify post_residual into usable zones.
    let zone = post_residual / 20; // 0..5 zones of size 20
    score -= match zone {
        0 => 30.0, // 0..19: nearly full, good closure
        1 => 10.0, // 20..39: still fillable by mid items
        2 => 5.0,
        3 => 0.0,
        _ => -5.0, // large residual: bin stays flexible
    };

    // Coupling with next item: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Next item leaves a harmonic residual after filling this bin's post space.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
        score -= 25.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when it enables a tight harmonic pairing
    // with the lookahead (empty bin residual == capacity, capacity % item sizes).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pair packing potential: reward a fresh bin for pairing
            score -= 55.0 - (bin_capacity - item_size - next_item_size) as f64 * 0.4;
        } else {
            // opening new bin wastefully: penalize relative to mean residual
            score += 120.0 + mean_residual * 0.8;
        }
    }

    // Fraction-of-capacity harmonic reward: post residual near a capacity fraction.
    for k in 1..4u32 {
        let frac = cap * (k as f64) / 4.0;
        if (pr - frac).abs() < 3.0 {
            score -= 20.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - pr) * 0.3;

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score += (pr - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are pure waste.
    if post_residual < 10 {
        score -= 25.0; // perfect/near-perfect fit is highly rewarded
    } else if post_residual <= 20 {
        // Gap too small for typical next items (>=10): mostly dead space.
        score += 6.0;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0; // gap remains usable
        } else if post_residual > 0 {
            score += 4.0; // gap useless for next item
        }
    }

    // Open-bin pressure: discourage scattering across many bins slightly.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral baseline, only chosen when fits are poor.
    if bin_residual == bin_capacity {
        score += 2.0 + (post_residual as f64 - bin_capacity as f64).abs() * 0.0;
        // mild progress-aware adjustment: later in stream, be slightly more frugal
        score -= (step_index as f64 / total_items.max(1) as f64) * 1.0;
    } else {
        // Prefer bins whose residual is close to item size (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 5.0;
        // Slight preference for bins below mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits leaving small usable remainder.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }
    // Dead space: post_residual too small for the next item (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size {
        // Small gaps (<10) are near-dead; large gaps relative to next item are worse.
        if post_residual <= 10 {
            score += 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Reward filling a bin completely (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and when many bins are already open (fragmentation control).
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if mean residual is large (open bins are full-ish), new bin is fine.
        score -= (mean_residual - 20.0).max(0.0) * 0.5;
        // Late in stream, prefer closing out residual space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for bins whose residual is near the mean (balanced use),
    // and penalize leaving residual far above mean (hoarding space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild tightening: prefer larger fills (smaller post_residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: post_residual that is too small to hold any plausible item
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for big items);
    // later, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.5 * crowding * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when the fit here is bad
    if bin_residual == bin_capacity {
        score += 20.0 * tightness; // empty bin has post_residual = capacity - item, tightness low => mild bonus
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight penalty proportional to wasted fraction of the bin
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress
    let mut score = post * (1.0 + 0.6 * progress * (1.0 - progress) * 4.0 * norm_post * (1.0 - norm_post));

    // Penalize large dead space non-linearly
    score += 12.0 * norm_post * norm_post * (1.0 + progress);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= 10.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: mildly discouraged early, more acceptable if it enables perfect fit for next item
    if bin_residual == bin_capacity {
        let mut penalty = 8.0 * (1.0 - progress);
        if next_item_size > 0 {
            let next_fit = (bin_capacity as f64 - next_item_size as f64) / cap;
            penalty -= 6.0 * next_fit * next_fit;
        }
        score += penalty.max(-4.0);
    }

    // Lookahead: reward if next item fits into resulting residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let slack = (post - next) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            score += 3.0 * ((next - post) / cap);
        }
    }

    // Mild regularization against bin proliferation
    score += 0.15 * open_bins_count as f64 * progress;

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = post - mean_residual;
    score += 0.05 * dev * (1.0 + progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
