    let mrn = mean_residual / cap ;
    if norm_pr < mrn * 0.5 { score += (mrn * 0.5 - norm_pr) * cap * 0.32 ; }
    if post_residual > 0 {
        if post_residual < 12 { score += (12 - post_residual) as f64 * 8.5 ; }
        else if post_residual < 30 { score += (30 - post_residual) as f64 * 1.2 ; }
        if next_item_size > 0 {
            if post_residual < next_item_size {
                let miss = (next_item_size - post_residual) as f64 ;
                score += miss * 1.5 + 2.0 * (1.0 - progress) ;
            } else {
                let gap = (post_residual - next_item_size) as f64 ;
                let slack = gap / cap ;
                score -= 4.0 + 8.0 * (1.0 - slack) ;
                if gap > next_item_size as f64 { score -= 1.5 ; }
                if post_residual < (next_item_size + item_size) as f64 { score -= 3.0 ; }
            }
        }
        if post_residual == next_item_size { score -= 6.0 ; }
        if post_residual == item_size { score -= 6.0 ; }
        if post_residual < item_size && post_residual >= next_item_size as u32 { score += 1.5 ; }
        if fitting_bins_count <= 1 && post_residual < item_size / 2 { score += 6.0 ; }
        if fitting_bins_count <= 2 && norm_pr > 0.9 { score -= 3.0 * (norm_pr - 0.9) ; }
        if fitting_bins_count >= 3 && norm_pr > 0.6 { score += 4.0 * (norm_pr - 0.6) ; }
        if fitting_bins_count == 1 && norm_pr > 0.5 { score -= 1.0 ; }
        if mean_residual > 0.0 && (pr - mean_residual) . abs () < cap * 0.05 { score -= 2.5 ; }
        if pr < mean_residual { score -= 2.0 ; }
    } else {
        score -= 25.0 ;
    }
    if bin_residual == bin_capacity {
        let tight = (next_item_size as f64 / cap) . min (1.0) ;
        score += 12.0 + 10.0 * (1.0 - progress) - 6.0 * tight * (1.0 - progress) ;
        if norm_pr > 0.6 && fitting_bins_count > 1 { score += 4.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common item
    // granularities (e.g. multiples of 10/20/25) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                harmony_bonus += (m as f64) * 0.6;
            }
        }
        // Perfect fit is best
        if pr == 0 {
            harmony_bonus += 200.0;
        }
        score -= harmony_bonus;
    } else {
        score -= 200.0;
    }

    // Penalize very small dead space (< 10 unusable) unless near zero
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            // reward smooth chaining, penalize awkward leftovers
            if leftover % 10 == 0 {
                score -= 40.0;
            } else {
                score += (leftover as f64) * 0.3;
            }
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / 10.0;
        score += 120.0 - 30.0 * crowd - 20.0 * progress;
        // If mean residual is large, prefer existing bins
        score += mean_residual * 0.5;
    }

    // Tight fits are good: small post_residual relative to capacity
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // Mean-residual alignment: prefer bins close to the mean (balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // Progress-based mild scaling to adapt over stream
    score *= 1.0 + 0.1 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

