    let mut score = post_residual as f64;

    // Penalize "unusable" small dead space: gaps below the minimum item size (1..100 range,
    // use a conservative small-gap threshold relative to capacity).
    let small_gap = 10.0f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < small_gap {
        // Dead space: heavily penalize, worse the closer to a full but wasted gap.
        score += (small_gap - post_residual as f64) * 6.0;
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is "rescued": post_residual that can still fit
    // the lookahead item keeps the bin useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot fit the next item.
        score += 3.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure proportional to open bins.
        score += 20.0 + (open_bins_count as f64) * 1.5;
        // Late in the stream, opening a new bin is less costly (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Slight bonus for using existing bins as pressure rises.
        score -= (open_bins_count as f64).ln() * 0.5;
    }

    // Mild penalty if this bin's residual deviates far above mean residual
    // (prefer balanced residual consumption).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

