pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals next item -> perfect chain
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward tightness of the chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            // extra reward for two-item exact fill (item + next == residual)
            if item_size + next_item_size == bin_residual {
                score -= 30.0;
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 12.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fits)
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Late in the stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it neutral-ish but slightly penalized so it's
    // chosen only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

