pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 60.0;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item could fit into the post-residual, reward leaving that space.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            // post-residual too small for next item: penalize dead space scaled by waste.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += dead * 0.8;
            }
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.5;

    // Discourage opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let avg_fit_penalty = 20.0 + 40.0 * (1.0 - progress);
        score += avg_fit_penalty;
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 15.0;
        }
    }

    // Mild penalty on large open-bin counts to discourage bin sprawl.
    score += open_bins_count as f64 * 0.3;

    score
}
